namespace Notifications;

/// <summary>Computes the backoff delay before the next delivery attempt.</summary>
public sealed class RetryPolicy
{
    public int NextDelay(int attempt, Channel channel, bool serverBusy)
    {
        if (attempt <= 0) return 0;
        if (attempt > 10) return 3600;

        var delay = GetBaseDelay(channel) * attempt;
        delay = ApplyBusyServerBackoff(delay, serverBusy);
        return ApplyLimitsAndLateAttemptAdjustment(delay, attempt);
    }

    private static int GetBaseDelay(Channel channel) => channel switch
    {
        Channel.Email => 30,
        Channel.Sms   => 10,
        Channel.Push  => 5,
        _             => 15
    };

    private static int ApplyBusyServerBackoff(int delay, bool serverBusy) =>
        serverBusy && delay < 600 ? delay * 2 : delay;

    private static int ApplyLimitsAndLateAttemptAdjustment(int delay, int attempt)
    {
        if (delay > 3600) return 3600;
        if (delay < 1) return 1;
        return attempt > 7 ? delay + 100 : delay;
    }
}
